using System.Text.Json;
using EliteMud.Tests.Server;

namespace EliteMud.Tests;

/// <summary>
/// Checks the rules content generated by "elitemud-import rules" (content/classes, races, progression).
/// The legacy source isn't in the repository, so these check the committed output.
/// </summary>
public class LegacyRulesContentTests
{
    private static readonly string Content = Path.Combine(RealWorld.RepositoryRoot, "content");

    [Theory]
    // Computed independently from titles[][] with legacy exp_needed() (limits.c), not with the extractor
    [InlineData(1, 2666)]
    [InlineData(2, 3332)]
    [InlineData(3, 4000)]
    [InlineData(4, 5333)]
    [InlineData(30, 1000000)]
    [InlineData(31, 1083333)]
    [InlineData(108, 40000000)]
    public void FighterCurve_MatchesLegacyExpNeeded(int level, int expected)
    {
        var thresholds = Read("progression/xp-curves/fighter.json").GetProperty("thresholds");

        Assert.Equal(109, thresholds.GetArrayLength());
        Assert.Equal(expected, thresholds[level - 1].GetInt32());
    }

    [Fact]
    public void Classes_HaveFortyTitlesAndValidReferences()
    {
        var curves = Ids("progression/xp-curves");
        var profiles = Ids("progression/level-up");

        foreach (var file in Directory.GetFiles(Path.Combine(Content, "classes"), "*.json"))
        {
            var cls = JsonDocument.Parse(File.ReadAllText(file)).RootElement;
            Assert.Equal(40, cls.GetProperty("titles").GetArrayLength());
            Assert.Contains(cls.GetProperty("xpCurve").GetString(), curves);
            Assert.Contains(cls.GetProperty("levelUpProfile").GetString(), profiles);
        }

        Assert.Equal(17, Directory.GetFiles(Path.Combine(Content, "classes"), "*.json").Length);
    }

    [Fact]
    public void Races_ReferenceExistingClasses_AndThirteenAreAvailableAtCreation()
    {
        var classes = Ids("classes");
        var races = Directory.GetFiles(Path.Combine(Content, "races"), "*.json")
            .Select(file => JsonDocument.Parse(File.ReadAllText(file)).RootElement)
            .ToList();

        Assert.Equal(25, races.Count);
        Assert.All(races.SelectMany(r => r.GetProperty("allowedClasses").EnumerateArray()), c => Assert.Contains(c.GetString(), classes));
        Assert.Equal(13, races.Count(r => r.GetProperty("availability").GetString() == "creation"));
    }

    [Fact]
    public void Paladin_LevelsLikeAFighter_ButGainsLikeAPriest()
    {
        // The legacy quirk the shared curves and profiles exist for
        var paladin = Read("classes/paladin.json");

        Assert.Equal("fighter", paladin.GetProperty("xpCurve").GetString());
        Assert.Equal("priest", paladin.GetProperty("levelUpProfile").GetString());
    }

    private static JsonElement Read(string path) =>
        JsonDocument.Parse(File.ReadAllText(Path.Combine(Content, path))).RootElement;

    private static HashSet<string?> Ids(string folder) =>
        Directory.GetFiles(Path.Combine(Content, folder), "*.json")
            .Select(file => JsonDocument.Parse(File.ReadAllText(file)).RootElement.GetProperty("id").GetString())
            .ToHashSet();
}
